def find_path(graph, start, goal):
    def dfs(node, path):
        # If the current node is the goal, return the current path
        if node == goal:
            return path + [goal]
        # Mark the current node as visited
        visited.add(node)
        # Check each neighbor
        for neighbor in graph[node]:
            if neighbor not in visited:
                # Recursively call dfs for the neighbor
                result = dfs(neighbor, path + [node])
                # If the neighbor leads to the goal, return the result
                if result:
                    return result
        # If no path to the goal was found, return None
        return None

    visited = set()
    return dfs(start, [start])

