def find_path(graph, start, goal):
    # Initialize open and closed sets
    open_set = set([start])
    closed_set = set()

    # Create a dictionary to store path cost from start to each node
    came_from = {}

    # Initialize cost to start to 0
    g_score = {node: float("infinity") for node in graph}
    g_score[start] = 0

    # Dictionary to store the lowest cost from start to goal through this node
    f_score = {node: float("infinity") for node in graph}
    f_score[start] = heuristic(start, goal)

    while open_set:
        current = None

        # Find the node with the lowest f_score value
        for node in open_set:
            if current is None or f_score[node] < f_score[current]:
                current = node

        if current == goal:
            # We have found the goal, reconstruct the path
            path = [current]
            while current in came_from:
                current = came_from[current]
                path.append(current)
            path.reverse()
            return path

        open_set.remove(current)
        closed_set.add(current)

        for neighbor, _ in graph[current]:
            if neighbor not in closed_set:
                tentative_g_score = g_score[current] + 1

                if neighbor not in open_set or tentative_g_score < g_score[neighbor]:
                    came_from[neighbor] = current
                    g_score[neighbor] = tentative_g_score
                    f_score[neighbor] = tentative_g_score + heuristic(neighbor, goal)

                    if neighbor not in open_set:
                        open_set.add(neighbor)

    # If the goal is unreachable, return None
    return None

